B.N5=new A.a1(58305,"MaterialIcons",!1)
B.KX=new A.N("tickets","Packed Suitcase","groom",0,"A suitcase at the bottom of his wardrobe, initialled G.C. Inside: a spare collar and two one-way train tickets to Biscotti Bay for tonight \u2014 \u201cMr. G. Cracker\u201d and \u201cMiss T. Misu\u201d.",B.N5,B.bm,"gwardrobe",B.j,B.c,!1,null)
