B.H5=new A.h(1,1,0.9529411764705882,0.8784313725490196,B.d)
B.L3=new A.N("eggs","Egg Basket","kitchen",4,"The egg basket on the counter, with yesterday's delivery slip: \u201c1 dozen, fresh.\u201d All twelve eggs are still in it. A Needy Souffl\xe9 takes six.",B.Nw,B.H5,null,B.j,B.c,!1,null)
B.MR=new A.a1(57994,"MaterialIcons",!1)
B.LA=new A.N("ovenash","Cold Oven","kitchen",2,"The kitchen oven. The firebox holds nothing but old grey ash, cold right through, and the coal scuttle beside it is full to the brim.",B.MR,B.fK,null,B.j,B.c,!1,null)
B.SV=s([B.L3,B.LA],t.F)
B.S6=s(["Please send a modern housekeeper at once.","The present one, P. Cotta,","is to be retired","without notice or pension.","She makes the same puddings as ever."],t.s)
B.Kp=new A.N("retire","Letter to an Agency","mbedroom",2,"On Mrs. Senclair's pillow, ready to post: \u201cPlease send a modern housekeeper at once. The present one, P. Cotta, is to be retired without notice or pension. She makes the same puddings she made thirty years ago.\u201d",B.be,B.I,null,B.f6,B.S6,!1,null)
B.PA=s([B.cJ,B.Kp],t.F)
B.Lo=new A.N("cakesack","Christmas Fruitcake","pantry",3,"Pushed deep into a flour sack: a fruitcake as hard as granite. One corner is freshly chipped, and there is custard on it. It wants dusting for fingerprints.",B.aC,B.af,"sacks",B.j,B.c,!1,null)
B.LW=new A.N("cakecrate","Christmas Fruitcake","storage",1,"At the bottom of a crate of old curtains: a fruitcake as hard as granite. One corner is freshly chipped, and there is custard on it. It wants dusting for fingerprints.",B.aC,B.af,"crates",B.j,B.c,!1,null)
B.L1=new A.N("cakekennel","Christmas Fruitcake","backyard",0,"Pushed to the back of the kennel: a fruitcake as hard as granite, with tooth marks where Pupcake gave up on it. One corner is freshly chipped, and there is custard on it. It wants dusting for fingerprints.",B.aC,B.af,"kennel",B.j,B.c,!1,null)
B.PX=s([B.Lo,B.LW,B.L1],t.F)
B.QU=s([B.dQ,B.PI,B.SV,B.PA,B.PX],t.Rt)
B.LD=new A.N("regiment","Letter from the Regiment","study",5,"In the desk drawer, a reply to Mrs. Senclair from Fort Fondant: \u201cMadam, we regret that we can find no record of any Colonel Cannoli among our fighting officers, nor of the medals you describe.\u201d",B.be,B.I,"desk",B.j,B.c,!1,null)
B.Kz=new A.N("ricottadrip","White Cream Drips","entrance",4,"A few spots of thick white ricotta on the floor at the top of the cellar steps, dried at the edges.",B.bJ,B.i,null,B.j,B.c,!1,null)
